package sem

// TEMPORARY: tree dump for issue #350 node-shape inspection. Do not commit.

import (
	"context"
	"fmt"
	"os"
	"strings"
	"testing"

	julia "github.com/entireio/entire-graph/internal/sem/grammars/julia"
	sitter "github.com/smacker/go-tree-sitter"
)

func TestZZTmpJuliaTreeDump(t *testing.T) {
	path := os.Getenv("ZZ_JULIA_DUMP")
	if path == "" {
		t.Skip("set ZZ_JULIA_DUMP")
	}
	src, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	parser := sitter.NewParser()
	parser.SetLanguage(julia.GetLanguage())
	tree, err := parser.ParseCtx(context.Background(), nil, src)
	if err != nil {
		t.Fatal(err)
	}
	var walk func(n *sitter.Node, field string, depth int)
	walk = func(n *sitter.Node, field string, depth int) {
		if depth > 6 {
			return
		}
		label := n.Type()
		if !n.IsNamed() {
			label = fmt.Sprintf("%q", n.Type())
		}
		if field != "" {
			label = field + ": " + label
		}
		text := strings.Join(strings.Fields(n.Content(src)), " ")
		if len(text) > 70 {
			text = text[:70] + "…"
		}
		fmt.Printf("%s%s [%d-%d] %s\n", strings.Repeat("  ", depth), label, n.StartByte(), n.EndByte(), text)
		for i := 0; i < int(n.ChildCount()); i++ {
			walk(n.Child(i), n.FieldNameForChild(i), depth+1)
		}
	}
	walk(tree.RootNode(), "", 0)
}

